import { generateHmacAuthHeaders } from '@forklaunch/core/http';
import type {
  GetOrganizationSubscriptionResponse,
  GetPlanResponse
} from './sdk.js';

/** Matches the application's SubscriptionCacheData. */
export type SurfacedSubscription = {
  subscriptionId: string;
  planId: string;
  planName: string;
  status: string;
  currentPeriodEnd: Date;
  features: string[];
};

/** The part of the application's BillingCacheService these helpers use. */
export interface SurfacingBillingCache {
  getCachedSubscription(
    organizationId: string
  ): Promise<SurfacedSubscription | null | undefined>;
  setCachedSubscription(
    organizationId: string,
    data: SurfacedSubscription
  ): Promise<unknown>;
  getCachedFeatures(
    organizationId: string
  ): Promise<Set<string> | null | undefined>;
  setCachedFeatures(
    organizationId: string,
    features: Set<string>
  ): Promise<unknown>;
}

/** JWT claims; the organization comes from the token. */
export type OrganizationClaims = {
  organizationId?: string;
  [claim: string]: unknown;
};

type Body<T> = T extends { code: 200; response: infer R } ? R : never;
type Subscription = Body<GetOrganizationSubscriptionResponse>;
type Plan = Body<GetPlanResponse>;

async function get<T>(
  billingUrl: string,
  hmacSecretKey: string,
  // HMAC signs the full wire path, without the query string.
  path: string
): Promise<T | undefined> {
  const response = await fetch(`${billingUrl.replace(/\/+$/, '')}${path}`, {
    method: 'GET',
    headers: {
      accept: 'application/json',
      ...generateHmacAuthHeaders({
        secretKey: hmacSecretKey,
        method: 'GET',
        path
      })
    }
  });
  if (response.status !== 200) {
    return undefined;
  }
  return (await response.json()) as T;
}

async function organizationPlan(
  billingUrl: string,
  hmacSecretKey: string,
  organizationId: string
): Promise<{ subscription: Subscription; plan?: Plan } | undefined> {
  const subscription = await get<Subscription>(
    billingUrl,
    hmacSecretKey,
    `/subscription/organization/${encodeURIComponent(organizationId)}`
  );
  if (!subscription) {
    return undefined;
  }
  const plan = await get<Plan>(
    billingUrl,
    hmacSecretKey,
    `/plan/${encodeURIComponent(subscription.productId)}`
  );
  return { subscription, plan };
}

/**
 * Create a surfaceSubscription function that fetches an organization's
 * subscription from billing with HMAC authentication and caches the result.
 */
export async function createSurfaceSubscription(params: {
  billingCacheService: SurfacingBillingCache;
  billingUrl: string;
  hmacSecretKey: string;
}): Promise<
  (payload: OrganizationClaims) => Promise<SurfacedSubscription | null>
> {
  const { billingCacheService, billingUrl, hmacSecretKey } = params;
  return async (payload: OrganizationClaims) => {
    if (!payload.organizationId) {
      throw new Error('organizationId is required in JWT payload');
    }
    const cached = await billingCacheService.getCachedSubscription(
      payload.organizationId
    );
    if (cached) {
      return cached;
    }
    try {
      const found = await organizationPlan(
        billingUrl,
        hmacSecretKey,
        payload.organizationId
      );
      if (!found) {
        return null;
      }
      const { subscription, plan } = found;
      const surfaced: SurfacedSubscription = {
        subscriptionId: subscription.id,
        planId: subscription.productId,
        planName: plan?.name ?? subscription.description ?? '',
        status: subscription.status,
        currentPeriodEnd: new Date(
          subscription.endDate ?? subscription.startDate
        ),
        features: plan?.features ?? []
      };
      await billingCacheService.setCachedSubscription(
        payload.organizationId,
        surfaced
      );
      return surfaced;
    } catch (error) {
      console.error(
        '[surfaceSubscription] Error surfacing subscription:',
        error
      );
      return null;
    }
  };
}

/**
 * Create a surfaceFeatures function that fetches an organization's plan
 * features from billing with HMAC authentication and caches the result.
 */
export async function createSurfaceFeatures(params: {
  billingCacheService: SurfacingBillingCache;
  billingUrl: string;
  hmacSecretKey: string;
}): Promise<(payload: OrganizationClaims) => Promise<Set<string>>> {
  const { billingCacheService, billingUrl, hmacSecretKey } = params;
  return async (payload: OrganizationClaims) => {
    if (!payload.organizationId) {
      throw new Error('organizationId is required in JWT payload');
    }
    const cached = await billingCacheService.getCachedFeatures(
      payload.organizationId
    );
    if (cached) {
      return cached;
    }
    try {
      const found = await organizationPlan(
        billingUrl,
        hmacSecretKey,
        payload.organizationId
      );
      const features = new Set<string>(found?.plan?.features ?? []);
      if (found) {
        await billingCacheService.setCachedFeatures(
          payload.organizationId,
          features
        );
      }
      return features;
    } catch (error) {
      console.error('[surfaceFeatures] Error surfacing features:', error);
      return new Set<string>();
    }
  };
}
